INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('mern-stack-development', 'MERN Stack Web Development', 'Development', 'Build scalable full-stack web applications using MongoDB, Express.js, React, and Node.js with modern production workflows.', 'A comprehensive, project-driven training curriculum designed to take you from foundational JavaScript through building, securing, and deploying multi-tier web applications. You will write clean modular code, design RESTful APIs, manage complex client state, and deploy to cloud environments.', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=1200&q=80', '4 Months', 'Intermediate', 'Classroom / In-Person', TRUE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday (6 Days/Week)","classTime":"Morning (7:00 AM – 9:00 AM) & Evening (5:00 PM – 7:00 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['JavaScript ES6+', 'React 18+', 'Node.js', 'Express.js', 'MongoDB & Mongoose', 'TypeScript', 'REST APIs', 'JWT Authentication', 'Git & GitHub', 'Postman', 'Tailwind CSS', 'Vercel / Render Deployment'], ARRAY['Students and graduates in Computer Science, BCA, BSc.CSIT, BIT, or engineering disciplines.', 'Aspiring developers with basic HTML/CSS/JS knowledge who want to build end-to-end applications.', 'Frontend developers wanting to master backend API architecture and database persistence.', 'Professionals seeking structured hands-on web engineering skills for technical employment in Nepal or remote.'], ARRAY['Basic familiarity with programming logic and HTML/CSS fundamentals.', 'A personal laptop for practical laboratory exercises and project development.'], ARRAY['Architect, build, and deploy production-ready full-stack applications.', 'Implement robust JWT token-based authentication and role-based access control (RBAC).', 'Design normalized and embedded MongoDB database schemas with indexing and aggregation pipelines.', 'Develop modular React frontends with reusable component architectures and state management.', 'Use Git branches, pull requests, and continuous deployment workflows.'], '[{"title":"Multi-Vendor E-Commerce Engine","technologies":["React","Node.js","MongoDB","Express","JWT"],"description":"Complete storefront with product catalog, cart persistence, vendor inventory management, order lifecycles, and Khalti/eSewa payment webhook integration.","type":"Full-Stack Web App"},{"title":"Collaborative Workspace & Task Management Platform","technologies":["React","TypeScript","Node.js","Socket.io","MongoDB"],"description":"Real-time kanban boards, task assignments, role permissions, activity audit trails, and live status notifications.","type":"Real-Time Application"},{"title":"Secure RESTful API Gateway for Healthcare Records","technologies":["Node.js","Express","Mongoose","Postman","Docker"],"description":"Comprehensive API with rate limiting, input sanitization, automated schema validation, and Swagger API documentation.","type":"Backend Service"}]'::jsonb, '[{"moduleNumber":"Module 01","title":"Modern JavaScript (ES6+) & TypeScript Foundations","topics":["Closures, Lexical Scope, and the JavaScript Event Loop","Promises, Async/Await, and Error Handling","Modular Architecture and Array/Object Transformations","TypeScript types, interfaces, generics, and strict compiler setups"],"practicalExercise":"Build an asynchronous CLI data processing utility and type-safe data validation system.","expectedOutcome":"Command strong modern JavaScript fundamentals without reliance on boilerplate libraries."},{"moduleNumber":"Module 02","title":"React Architecture & Modern Frontend Engineering","topics":["Component lifecycle, Virtual DOM, and reconciliation","Custom hooks, useMemo, useCallback, and Context API","Form management, React Hook Form, and Zod validation","Tailwind CSS design systems, responsive UI patterns, and routing"],"practicalExercise":"Develop an interactive analytics dashboard with client-side filters, paginated tables, and dark/light UI modes.","expectedOutcome":"Create responsive, accessible, and maintainable user interfaces with React."},{"moduleNumber":"Module 03","title":"Node.js, Express & Server-Side API Architecture","topics":["Event-driven Node.js architecture and Streams","RESTful design principles, routing, and custom middleware","JWT authentication, bcrypt hashing, and cookie security","Error middleware, Winston logging, and request validation"],"practicalExercise":"Build a production-grade auth and user management API with refresh token rotation.","expectedOutcome":"Construct secure, modular server-side architectures ready for production workloads."},{"moduleNumber":"Module 04","title":"MongoDB Database Design & Aggregation Pipelines","topics":["Document modeling vs relational schemas","Mongoose schema definitions, hooks, and virtuals","Complex aggregations, indexing strategies, and lookup operations","Data migration and backup procedures"],"practicalExercise":"Design and benchmark a scalable database schema for an e-commerce catalog with search filters.","expectedOutcome":"Store, query, and optimize document databases effectively."},{"moduleNumber":"Module 05","title":"Capstone Project, Code Reviews & Deployment","topics":["Git workflows, GitHub Actions CI/CD basics","Environment management and production security headers (Helmet, CORS)","Deploying client to Vercel and API to Render/DigitalOcean/AWS","Technical presentation and code walkthrough"],"practicalExercise":"Deploy a complete full-stack capstone project to a live public URL with full documentation.","expectedOutcome":"A live portfolio project and practical experience in end-to-end deployment."}]'::jsonb, ARRAY['Full Stack Developer (MERN)', 'Frontend Developer (React)', 'Backend Developer (Node.js/Express)', 'Junior Software Engineer', 'Web Application Engineer'], '{"name":"[Senior Software Engineer at Navya EdTech / Industry Practitioner]","role":"Full Stack Engineering Lead","experience":"6+ years in commercial web applications and distributed systems","specialization":"Node.js, React, Distributed Architecture, Scalable Databases","isPlaceholder":true}'::jsonb, '[{"question":"Who is eligible to enroll in this MERN stack course?","answer":"Anyone with a basic understanding of computer operations and programming logic. Prior experience with HTML, CSS, or basic JavaScript is helpful but we also cover modern JS fundamentals thoroughly in the initial weeks."},{"question":"Is this training available in-person in Kathmandu or online?","answer":"We offer both physical classroom sessions at our Kathmandu training facility and interactive online live sessions with hands-on lab support."},{"question":"Will I build real projects during the course?","answer":"Yes. Every module includes mandatory practical assignments, and the final 4 weeks are dedicated to architecting and deploying an end-to-end full-stack capstone project."},{"question":"Do you provide course completion certificates?","answer":"Yes, students who successfully complete all module projects and their capstone evaluation receive a verified Certificate of Completion from Navya Ed Tech Pvt. Ltd."},{"question":"How do I enquire about the next batch and fees?","answer":"Click \"Talk to an Advisor\" or fill out the enquiry form on this page. Our education advisory team will reach out with the batch timings, curriculum outline, and fee details."}]'::jsonb, 'MERN Stack Course in Nepal | Full Stack Web Development Training Kathmandu', 'Master MERN stack web development in Nepal with Navya Ed Tech. Learn React, Node.js, Express, and MongoDB through real project development.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('python-data-science-ai', 'Python, Data Science & Machine Learning', 'Data & AI', 'Master modern Python programming, statistical data analysis, machine learning models, and practical AI workflow implementation.', 'Designed for analytical minds wanting to harness Python for data analysis, business intelligence, predictive modeling, and applied machine learning. Learn to manipulate datasets with Pandas and NumPy, build predictive models with Scikit-Learn, and understand modern AI integration techniques.', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=1200&q=80', '3.5 Months', 'Beginner to Intermediate', 'Classroom / In-Person', TRUE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday","classTime":"Morning (6:30 AM – 8:30 AM) & Evening (4:30 PM – 6:30 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['Python 3.12+', 'NumPy', 'Pandas', 'Matplotlib & Seaborn', 'Scikit-Learn', 'Jupyter Labs', 'SQL & PostgreSQL', 'FastAPI', 'Git & GitHub', 'Applied LLM APIs'], ARRAY['Undergraduates and professionals in STEM, economics, finance, or business analytics.', 'Developers transitioning into data analysis and machine learning engineering.', 'Anyone looking to develop strong programmatic problem-solving with Python.'], ARRAY['High-school level mathematics and logical problem-solving aptitude.', 'No mandatory prior coding experience required; Python starts from foundational syntax.'], ARRAY['Clean, transform, and analyze complex unstructured and structured datasets.', 'Build end-to-end supervised and unsupervised machine learning pipelines.', 'Deploy predictive ML models as production REST APIs using FastAPI.', 'Perform exploratory data analysis (EDA) with publication-quality visualizations.', 'Integrate AI services and embedding workflows into practical applications.'], '[{"title":"Customer Churn & Risk Prediction Engine","technologies":["Python","Pandas","Scikit-Learn","FastAPI"],"description":"End-to-end machine learning system that ingests historical customer telemetry to predict churn probabilities with explainable feature importance.","type":"Machine Learning Pipeline"},{"title":"Automated Financial Market & Inflation Analytics System","technologies":["Python","Pandas","Matplotlib","PostgreSQL"],"description":"Time-series data aggregation, automated anomaly detection, and interactive reporting dashboard for financial metrics.","type":"Data Analysis Platform"},{"title":"Document Semantic Search & Q&A Service","technologies":["Python","FastAPI","Vector Embeddings","Postman"],"description":"Applied AI service that embeds technical documentation for high-accuracy semantic retrieval and contextual summarization.","type":"AI / Backend Service"}]'::jsonb, '[{"moduleNumber":"Module 01","title":"Python Core Architecture & Algorithmic Problem Solving","topics":["Data structures: lists, tuples, sets, dictionaries, and list comprehensions","Object-Oriented Programming (OOP) in Python: classes, inheritance, dunder methods","File I/O, exception handling, and virtual environments","Writing clean PEP 8 compliant code"],"practicalExercise":"Develop a modular data parser and automated report generator in pure Python.","expectedOutcome":"Write idiomatic, maintainable Python code."},{"moduleNumber":"Module 02","title":"Data Wrangling, Analysis & SQL Integration","topics":["NumPy multi-dimensional arrays, vectorization, and broadcasting","Pandas DataFrames: indexing, filtering, merging, and groupby aggregations","Handling missing values, outlier detection, and data cleansing","Relational database querying with SQL & SQLAlchemy"],"practicalExercise":"Clean and merge multi-source business datasets to generate actionable analytical metrics.","expectedOutcome":"Confidently clean and analyze real-world datasets."},{"moduleNumber":"Module 03","title":"Exploratory Data Analysis & Statistical Modeling","topics":["Descriptive and inferential statistics fundamentals","Hypothesis testing, correlation analysis, and distributions","Advanced visualizations with Seaborn and Matplotlib","Storytelling with data for stakeholders"],"practicalExercise":"Produce a comprehensive Exploratory Data Analysis report with statistical hypotheses.","expectedOutcome":"Uncover patterns, anomalies, and insights from complex data."},{"moduleNumber":"Module 04","title":"Machine Learning Pipelines with Scikit-Learn","topics":["Supervised learning: Linear Regression, Logistic Regression, Decision Trees, Random Forests","Unsupervised learning: K-Means clustering, PCA dimensionality reduction","Cross-validation, hyperparameter tuning (GridSearchCV), and evaluation metrics","Building reproducible Scikit-Learn Pipelines"],"practicalExercise":"Train and optimize a classification model with strict cross-validation safeguards against data leakage.","expectedOutcome":"Develop, evaluate, and tune robust machine learning models."},{"moduleNumber":"Module 05","title":"Model Deployment, FastAPI & AI Systems","topics":["Exporting models (Joblib/Pickle) and serving predictions via FastAPI","Input validation with Pydantic and API testing","Introduction to modern AI APIs, embeddings, and vector databases","Final capstone evaluation and technical presentation"],"practicalExercise":"Deploy an interactive ML API endpoint with live documentation and test client.","expectedOutcome":"Deliver functioning data and ML services that integrate with web applications."}]'::jsonb, ARRAY['Data Analyst', 'Junior Machine Learning Engineer', 'Python Backend Developer', 'Business Intelligence Developer', 'AI Solutions Associate'], '{"name":"[Data & AI Practitioner at Navya EdTech / Industry Specialist]","role":"Data Science & Machine Learning Lead","experience":"5+ years in data modeling, statistical computing, and predictive systems","specialization":"Python, Predictive Analytics, Applied Machine Learning, FastAPI","isPlaceholder":true}'::jsonb, '[{"question":"Do I need a strong mathematical or coding background to start?","answer":"Basic high-school mathematics and logical reasoning are sufficient. We teach Python syntax from scratch and build up statistical concepts intuitively with code examples."},{"question":"What kind of projects will I complete in this course?","answer":"You will work on real datasets covering customer churn prediction, financial analysis, exploratory data reporting, and a production FastAPI model deployment."},{"question":"Are classes hands-on with lab sessions?","answer":"Yes, every lecture is accompanied by code-along exercises and Jupyter notebook laboratory sessions."}]'::jsonb, 'Python & Data Science Course in Nepal | Machine Learning Training Kathmandu', 'Learn Python programming, data analytics, and machine learning in Nepal with Navya Ed Tech. Hands-on projects with Pandas, Scikit-Learn, and FastAPI.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('ui-ux-product-design', 'UI/UX & Digital Product Design', 'Design', 'Master user research, wireframing, design systems, Figma workflows, and high-fidelity prototyping for modern digital products.', 'Learn to design intuitive, aesthetically refined, and accessible user interfaces. This course bridges user research, information architecture, typography, color theory, design systems, and responsive UX design tailored to real enterprise and consumer software products.', 'https://images.unsplash.com/photo-1581291518857-4e27b48ff24e?auto=format&fit=crop&w=1200&q=80', '3 Months', 'Beginner to Intermediate', 'Hybrid (Classroom & Online)', TRUE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday","classTime":"Morning (7:00 AM – 8:30 AM) & Evening (5:30 PM – 7:00 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['Figma (Advanced)', 'Design Systems & Tokens', 'Wireframing & Prototyping', 'User Research & Personas', 'Information Architecture', 'WCAG Accessibility', 'Responsive Grids', 'Developer Handoff', 'Micro-interactions'], ARRAY['Aspiring product designers, UI designers, and visual creators.', 'Frontend developers looking to deepen their design sensibilities and user experience rigor.', 'Product managers and entrepreneurs wanting to prototype ideas cleanly.'], ARRAY['Basic familiarity with computers and a genuine interest in visual problem solving.', 'No prior graphic design software experience required.'], ARRAY['Conduct user interviews, synthesize research, and build actionable journey maps.', 'Build scalable multi-brand design systems in Figma using auto-layout, variables, and components.', 'Design accessible, responsive web and mobile interfaces that meet WCAG AA standards.', 'Create interactive prototypes with realistic component states and micro-interactions.', 'Assemble an industry-grade UX portfolio case study.'], '[{"title":"FinTech Banking & Remittance Mobile Experience","technologies":["Figma","Auto-Layout","Interactive Prototypes","Design System"],"description":"End-to-end mobile design case study solving transaction clarity, biometric verification, and localized payment flows for Nepali users.","type":"Mobile App Design Case Study"},{"title":"B2B SaaS Analytics & Management Dashboard","technologies":["Figma","Design Tokens","Information Architecture","Responsive Grids"],"description":"Complex data-dense desktop software with multi-level navigation, table views, filter drawers, and component state specifications.","type":"Desktop Web App Case Study"},{"title":"E-Commerce Checkout & Micro-Interactions Optimization","technologies":["Figma","Usability Testing","Design System"],"description":"Conversion-focused checkout overhaul addressing cognitive load, form errors, and friction points.","type":"UX Audit & Redesign"}]'::jsonb, '[{"moduleNumber":"Module 01","title":"UX Research & Information Architecture Fundamentals","topics":["User-centered design methodology and Double Diamond framework","Conducting user interviews and creating user personas","User journey mapping, empathy maps, and problem framing","Information architecture, card sorting, and user flow diagrams"],"practicalExercise":"Conduct research for a digital service in Nepal and develop structured user journey maps.","expectedOutcome":"Ground design decisions in verified user needs."},{"moduleNumber":"Module 02","title":"Wireframing, Layouts & Visual Design Foundations","topics":["Low-fidelity sketching and paper prototyping","Typography hierarchy, scale ratios, and font pairing","Color theory, contrast ratios, and accessible palette generation","8pt spatial grid system and layout math"],"practicalExercise":"Design wireframes and visual style guides for responsive viewport breakpoints.","expectedOutcome":"Create structured, balanced visual layouts."},{"moduleNumber":"Module 03","title":"Figma Mastery: Components, Auto-Layout & Design Systems","topics":["Mastering Figma Auto-Layout (nesting, wrap, min/max constraints)","Component variants, properties, slots, and interactive states","Design tokens and Figma variables (colors, typography, spacing, modes)","Structuring multi-page design libraries for team collaboration"],"practicalExercise":"Build a production-grade UI kit with 25+ reusable responsive components and dark/light modes.","expectedOutcome":"Construct professional design systems ready for production scaling."},{"moduleNumber":"Module 04","title":"Interactive Prototyping & Usability Evaluation","topics":["Smart animate, interactive components, and micro-interactions","Simulating scroll physics, overlay modals, and conditional states","Planning and executing moderated usability tests","Synthesizing feedback into iterative design improvements"],"practicalExercise":"Build a clickable high-fidelity mobile prototype and record a structured usability test session.","expectedOutcome":"Validate interaction models with realistic prototypes."},{"moduleNumber":"Module 05","title":"Developer Handoff & Portfolio Case Study Building","topics":["Dev mode, redlines, asset exports, and design annotations","Writing comprehensive UX case studies (Context, Problem, Process, Solution, Impact)","Structuring a portfolio presentation on Behance/Dribbble/Custom domain","Design review and critique with industry practitioners"],"practicalExercise":"Publish a complete end-to-end design case study ready for employer review.","expectedOutcome":"Graduate with an industry-ready UI/UX portfolio."}]'::jsonb, ARRAY['UI/UX Designer', 'Product Designer', 'User Experience Researcher', 'Interaction Designer', 'Visual Designer'], '{"name":"[Lead Product Designer at Navya EdTech / Design Consultant]","role":"Lead UI/UX Designer","experience":"6+ years designing enterprise SaaS, consumer mobile apps, and web platforms","specialization":"Design Systems, Figma, Mobile Interaction, Usability Engineering","isPlaceholder":true}'::jsonb, '[{"question":"Do I need to know coding to become a UI/UX designer?","answer":"No coding is required. UI/UX focuses on user psychology, research, interface design, and prototyping in Figma. We do teach you how to collaborate smoothly with developers during handoff."},{"question":"What tools will I learn?","answer":"You will achieve high proficiency in Figma, design system libraries, FigJam, and usability testing tools."},{"question":"Will I have a finished portfolio after the course?","answer":"Yes. You will complete and document at least two comprehensive UX case studies formatted for your professional portfolio."}]'::jsonb, 'UI UX Design Course in Nepal | Product Design Training Kathmandu', 'Learn UI/UX design in Kathmandu with Navya Ed Tech. Master Figma, design systems, user research, wireframing, and portfolio case studies.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('react-frontend-engineering', 'React & Modern Frontend Engineering', 'Development', 'Master React 18+, TypeScript, state management, modern build tooling, performance optimization, and clean component architecture.', 'A deep-dive frontend program focusing on building robust, performant web applications. You will master React fundamentals, hooks architecture, TypeScript integration, client-side caching with TanStack Query, styling with Tailwind, and production deployment.', 'https://images.unsplash.com/photo-1633356122544-f134324a6cee?auto=format&fit=crop&w=1200&q=80', '2.5 Months', 'Intermediate', 'Classroom / In-Person', FALSE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday","classTime":"Morning & Evening batches available","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['React 18+', 'TypeScript', 'Vite & Next.js Basics', 'Tailwind CSS', 'TanStack Query', 'Zustand / Redux Toolkit', 'React Router 6+', 'Zod & React Hook Form', 'Git & CI/CD'], ARRAY['Developers with JavaScript basics wanting to master production React development.', 'Backend developers looking to gain serious modern frontend proficiency.', 'Computer science students preparing for frontend developer interviews.'], ARRAY['Solid foundation in JavaScript (ES6 syntax, DOM manipulation, async/await).', 'Basic HTML5 and CSS3 proficiency.'], ARRAY['Write scalable, type-safe React applications with TypeScript.', 'Implement efficient server-state synchronization with TanStack Query.', 'Optimize React rendering performance, code-splitting, and memoization.', 'Build responsive, accessible component design systems with Tailwind CSS.'], '[{"title":"Project Management & Team Workspace App","technologies":["React","TypeScript","Tailwind CSS","Zustand","TanStack Query"],"description":"Rich client-side application with drag-and-drop task boards, filter presets, optimistic UI updates, and offline sync caching.","type":"Interactive SPA"},{"title":"Stock Market & Crypto Telemetry Terminal","technologies":["React","TypeScript","Recharts","WebSockets"],"description":"High-frequency data visualization dashboard rendering interactive charts, custom timeframe selectors, and real-time feeds.","type":"Data Visualization"}]'::jsonb, '[{"moduleNumber":"Module 01","title":"React Fundamentals & Component Architecture","topics":["JSX compilation","Props, State, and Pure Functions","Conditional rendering and lists","Lifecycle and side effects"],"practicalExercise":"Build an interactive filterable product catalog with URL state sync.","expectedOutcome":"Master core React primitives."},{"moduleNumber":"Module 02","title":"TypeScript with React & Advanced Hooks","topics":["Typing Props, State, Events, and Refs","Custom Hooks patterns","useCallback, useMemo, and React.memo","Context API vs lightweight state"],"practicalExercise":"Develop a type-safe form builder with dynamic fields and validation.","expectedOutcome":"Write type-safe React without compile errors."},{"moduleNumber":"Module 03","title":"State Management & Async Server Data","topics":["Client state with Zustand","Server state with TanStack Query (fetching, caching, mutations, pagination)","Optimistic updates","Error boundaries"],"practicalExercise":"Integrate a complex REST API with optimistic mutations and infinite scrolling.","expectedOutcome":"Handle complex async data with zero UI jank."},{"moduleNumber":"Module 04","title":"Design Systems, Performance & Production Build","topics":["Tailwind CSS architectures","Headless UI & accessibility","Vite bundle optimization and dynamic imports","Automated testing overview"],"practicalExercise":"Audit and optimize an existing React app for Lighthouse performance 95+ score.","expectedOutcome":"Deliver production-grade frontend web applications."}]'::jsonb, ARRAY['Frontend Engineer (React)', 'React Developer', 'JavaScript Web Developer', 'UI Engineer'], '{"name":"[Senior Frontend Engineer at Navya EdTech]","role":"Frontend Engineering Lead","experience":"5+ years in modern JavaScript, SPA architectures, and frontend performance","specialization":"React, TypeScript, Next.js, Performance Optimization","isPlaceholder":true}'::jsonb, '[{"question":"Is TypeScript mandatory for this course?","answer":"We introduce TypeScript step-by-step from week two. Modern industry standards require TypeScript, so we ensure you learn it naturally alongside React."}]'::jsonb, 'React JS Course in Nepal | Frontend Web Development Training Kathmandu', 'Master React.js and TypeScript in Kathmandu with Navya Ed Tech. Hands-on project based training in modern frontend engineering.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('devops-cloud-engineering', 'DevOps & Cloud Engineering', 'Cloud & DevOps', 'Learn Linux systems administration, Docker containerization, CI/CD pipelines, Kubernetes basics, and AWS cloud infrastructure management.', 'Equip yourself with the tools and mindsets used by modern site reliability and DevOps teams. Master Linux command line operations, containerize multi-tier apps with Docker, automate testing and deployment with GitHub Actions, and provision cloud infrastructure on AWS.', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=1200&q=80', '3 Months', 'Intermediate to Advanced', 'Classroom / In-Person', FALSE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday","classTime":"Morning & Evening sessions","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['Linux Administration', 'Bash Scripting', 'Docker & Docker Compose', 'Kubernetes (K8s) Basics', 'AWS (EC2, S3, RDS, IAM)', 'GitHub Actions CI/CD', 'Nginx & Reverse Proxies', 'Terraform Basics', 'Prometheus & Grafana'], ARRAY['Software developers wanting to master deployment, containerization, and infrastructure.', 'System administrators transitioning into modern cloud automation and DevOps.', 'IT graduates seeking high-demand infrastructure engineering roles.'], ARRAY['Basic familiarity with operating systems and networking concepts.', 'Fundamental command line comfort.'], ARRAY['Administer secure Linux servers, users, permissions, and systemd services.', 'Containerize full-stack applications with multi-stage Docker builds.', 'Build automated CI/CD deployment pipelines using GitHub Actions.', 'Deploy and manage web workloads on AWS cloud infrastructure.', 'Configure Nginx reverse proxies, SSL certificates (Certbot), and domain routing.'], '[{"title":"Zero-Downtime Multi-Tier CI/CD Pipeline","technologies":["GitHub Actions","Docker","AWS EC2","Nginx"],"description":"Automated workflow that runs tests, builds Docker containers, publishes to registry, and executes zero-downtime rolling deployment to cloud instances.","type":"DevOps Pipeline"},{"title":"Microservices Infrastructure with Docker Compose & Nginx","technologies":["Docker","Nginx","PostgreSQL","Redis","Certbot"],"description":"Containerized infrastructure running multiple services behind an Nginx reverse proxy with automated Let''s Encrypt SSL renewal.","type":"Infrastructure Deployment"}]'::jsonb, '[{"moduleNumber":"Module 01","title":"Linux Systems Administration & Bash Automation","topics":["Linux filesystem hierarchy, permissions, and user management","Process management, systemd services, and cron jobs","Networking: DNS, SSH keys, firewalls (UFW/iptables), curl","Writing robust Bash automation scripts"],"practicalExercise":"Provision a secured headless Linux VM with automated user and security scripts.","expectedOutcome":"Master Linux server administration."},{"moduleNumber":"Module 02","title":"Docker Containerization & Multi-Stage Builds","topics":["Container concepts vs virtualization","Dockerfile instructions, caching, and multi-stage builds","Docker networking, volumes, and data persistence","Orchestration with Docker Compose for local environments"],"practicalExercise":"Containerize a multi-tier web application (Node API + React + MongoDB) with optimized image sizes.","expectedOutcome":"Containerize any software stack reliably."},{"moduleNumber":"Module 03","title":"AWS Cloud Architecture & Infrastructure Essentials","topics":["AWS IAM policies, roles, and security groups","Compute with EC2 and auto-scaling basics","Storage with S3 and database hosting with RDS","VPC basics and public/private subnets"],"practicalExercise":"Deploy a high-availability web service on AWS with managed database and storage.","expectedOutcome":"Provision and configure core AWS cloud services."},{"moduleNumber":"Module 04","title":"CI/CD Pipelines, Nginx & Monitoring","topics":["GitHub Actions workflows, secrets, and runners","Nginx reverse proxy, load balancing, and SSL","Log aggregation and basic server monitoring with Prometheus/Grafana","Disaster recovery and backup strategies"],"practicalExercise":"Construct an end-to-end automated deployment pipeline triggered on git push.","expectedOutcome":"Automate build, test, and release cycles from source control."}]'::jsonb, ARRAY['DevOps Engineer', 'Cloud Support Engineer', 'System & Infrastructure Administrator', 'Site Reliability Engineer (Associate)', 'Build & Release Specialist'], '{"name":"[Cloud & Infrastructure Lead at Navya EdTech / Industry Specialist]","role":"DevOps & Cloud Engineer","experience":"7+ years managing production cloud infrastructure and automated pipelines","specialization":"AWS, Docker, Linux Systems, CI/CD, Kubernetes","isPlaceholder":true}'::jsonb, '[{"question":"Do I need an AWS credit card/account for class?","answer":"We guide you through setting up the AWS Free Tier and provide shared laboratory environments for practical coursework."}]'::jsonb, 'DevOps & AWS Cloud Course in Nepal | Infrastructure Training Kathmandu', 'Learn DevOps, Docker, Linux, CI/CD, and AWS cloud engineering in Kathmandu with Navya Ed Tech. Hands-on practical infrastructure training.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('cybersecurity-fundamentals', 'Cybersecurity Fundamentals & Network Defense', 'Cybersecurity', 'Understand network security, vulnerability assessment, ethical hacking concepts, web application security (OWASP Top 10), and defensive hardening.', 'A structured foundation in practical information security. Learn how networks communicate, identify common attack vectors, analyze web vulnerabilities using industry standard tools, and implement defensive countermeasures to protect digital assets.', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=1200&q=80', '3 Months', 'Beginner to Intermediate', 'Classroom / In-Person', FALSE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday","classTime":"Morning & Evening batches","seatsStatus":"Admissions Open","location":"Kathmandu Campus"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['Kali Linux', 'Wireshark', 'Nmap', 'Burp Suite Community', 'OWASP Top 10', 'Metasploit Basics', 'Network Protocols (TCP/IP, DNS, SSL)', 'Firewalls & IDS/IPS Concepts'], ARRAY['IT students and graduates interested in cybersecurity and ethical security analysis.', 'System administrators and network engineers wishing to strengthen defensive capabilities.', 'Developers wanting to build secure software from the ground up.'], ARRAY['Basic understanding of networking concepts (IP addresses, ports, routers).', 'High standard of ethical responsibility and commitment to legal security practices.'], ARRAY['Inspect and analyze network packets with Wireshark to spot anomalies.', 'Perform structured vulnerability assessments on test networks with Nmap and Nessus.', 'Test web applications against OWASP Top 10 vulnerabilities (SQLi, XSS, CSRF, IDOR).', 'Configure system hardening, password policies, and security logging.'], '[{"title":"Comprehensive Web Application Penetration Test Report","technologies":["Burp Suite","OWASP ZAP","Kali Linux"],"description":"Structured vulnerability assessment of an intentionally vulnerable enterprise lab environment with formal remediation recommendations.","type":"Security Assessment"},{"title":"Network Defense & Intrusion Detection Lab","technologies":["Wireshark","Snort","Linux"],"description":"Simulated network environment with configured intrusion rules to detect port scans, brute-force attempts, and unauthorized data exfiltration.","type":"Defensive Lab"}]'::jsonb, '[{"moduleNumber":"Module 01","title":"Networking & Operating System Security Foundations","topics":["TCP/IP model, packet structure, subnetting","Common protocols: DNS, HTTP/HTTPS, SSH, DHCP","Linux and Windows security baselines","Setting up a virtualized Kali security lab"],"practicalExercise":"Configure and isolate a security lab using VirtualBox/VMware.","expectedOutcome":"Build a secure testing environment."},{"moduleNumber":"Module 02","title":"Network Reconnaissance & Vulnerability Scanning","topics":["Passive and active reconnaissance","Port scanning and service detection with Nmap","Vulnerability scanning workflows","Packet inspection with Wireshark"],"practicalExercise":"Map a target network subnet and identify exposed legacy services.","expectedOutcome":"Identify network security gaps before attackers do."},{"moduleNumber":"Module 03","title":"Web Application Security & OWASP Top 10","topics":["HTTP request/response analysis with Burp Suite proxy","SQL Injection (SQLi) and prevention with parameterized queries","Cross-Site Scripting (XSS) and Content Security Policy (CSP)","Authentication bypass and broken access controls"],"practicalExercise":"Identify and remediate 5 distinct OWASP vulnerabilities in a controlled lab application.","expectedOutcome":"Audit and secure modern web applications."},{"moduleNumber":"Module 04","title":"System Hardening, Incident Response & Reporting","topics":["Endpoint protection, firewalls, and least-privilege principles","Security logging, SIEM basics, and alert triage","Writing professional vulnerability assessment reports","Ethics, legal standards, and industry certifications (Security+, CEH) overview"],"practicalExercise":"Author a professional executive summary and technical remediation report.","expectedOutcome":"Communicate technical security findings clearly to technical and executive stakeholders."}]'::jsonb, ARRAY['Junior Security Analyst (SOC Tier 1)', 'Vulnerability Assessment Associate', 'Network Security Specialist', 'Information Security Auditor'], '{"name":"[Certified Information Security Specialist at Navya EdTech / Consultant]","role":"Cybersecurity Instructor","experience":"6+ years in vulnerability research, network auditing, and incident response","specialization":"Network Security, OWASP, Penetration Testing, System Hardening","isPlaceholder":true}'::jsonb, '[{"question":"Are the security testing practices legal?","answer":"All practical lab exercises are conducted strictly inside isolated local virtual environments and designated vulnerable practice platforms under clear ethical guidelines."}]'::jsonb, 'Cybersecurity Training in Nepal | Ethical Hacking & Security Course Kathmandu', 'Learn cybersecurity fundamentals, network defense, and web security testing in Kathmandu with Navya Ed Tech.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('flutter-mobile-app-development', 'Flutter & Cross-Platform Mobile App Development', 'Development', 'Build native iOS and Android mobile applications using Google Flutter and Dart with clean architecture, state management, and backend integrations.', 'Learn to design, develop, and publish fluid cross-platform mobile apps for iOS and Android from a single codebase. Master Dart language fundamentals, widget composition, state management with Bloc/Provider, SQLite local databases, and REST API integration.', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?auto=format&fit=crop&w=1200&q=80', '3 Months', 'Beginner to Intermediate', 'Classroom / In-Person', FALSE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday","classTime":"Morning & Evening batches","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['Dart Programming', 'Flutter SDK 3+', 'Bloc / Riverpod State Management', 'REST API Integration (Dio/Http)', 'SQLite & Hive Local Storage', 'Firebase Mobile Services', 'Push Notifications', 'Google Play / App Store Deployment'], ARRAY['Beginners and web developers wanting to build native mobile apps for iOS and Android.', 'Computer science students preparing for mobile developer careers.', 'Entrepreneurs building custom mobile MVPs.'], ARRAY['Basic programming understanding (any language: C, C++, Java, JS, or Python).', 'A computer capable of running Android Studio / Xcode simulator.'], ARRAY['Build smooth, responsive 60fps mobile interfaces in Flutter.', 'Implement clean architecture and reliable state management using Bloc or Riverpod.', 'Store data offline with local SQLite/Hive databases and synchronize with REST APIs.', 'Package and prepare apps for the Google Play Store.'], '[{"title":"Ride-Hailing & Logistics Mobile App","technologies":["Flutter","Google Maps SDK","Bloc","REST API"],"description":"Interactive booking flow, live driver location tracking, localized routes, fare calculation, and cash/digital wallet checkout.","type":"Mobile App"},{"title":"Personal Finance & Expense Tracker with Offline Sync","technologies":["Flutter","Hive DB","FL Chart","Clean Architecture"],"description":"Comprehensive budget manager with visual analytics, category budgets, receipt attachments, and offline-first data sync.","type":"Mobile App"}]'::jsonb, '[{"moduleNumber":"Module 01","title":"Dart Language Mastery & Object-Oriented Design","topics":["Variables, types, functions, and control flow","OOP: Classes, Mixins, Abstract Classes, and Interfaces","Null safety, collections, and higher-order functions","Async programming: Futures, Streams, and isolates"],"practicalExercise":"Write an asynchronous financial calculation engine in pure Dart.","expectedOutcome":"Command Dart syntax with confidence."},{"moduleNumber":"Module 02","title":"Flutter UI Composition & Custom Widgets","topics":["Stateless vs Stateful widgets","Layout primitives: Row, Column, Stack, Flex, Wrap","Material 3 and Cupertino UI widgets","Custom animations and responsive layout builders"],"practicalExercise":"Construct an aesthetic multi-screen e-commerce product UI.","expectedOutcome":"Build pixel-perfect mobile layouts."},{"moduleNumber":"Module 03","title":"State Management & Architecture Patterns","topics":["State management comparison: setState, Provider, Bloc/Cubit, Riverpod","Clean Architecture layer separation (Data, Domain, Presentation)","Dependency injection with GetIt","Handling form states and user inputs"],"practicalExercise":"Implement a complete authentication and cart management flow using Bloc.","expectedOutcome":"Architect scalable mobile codebases without spaghetti state."},{"moduleNumber":"Module 04","title":"APIs, Local Persistence & Store Release","topics":["HTTP clientDio, interceptors, error handling","Local databases with SQLite (sqflite) and Hive","Push notifications, device permissions (Camera, GPS)","App signing, ProGuard, and Google Play Store submission prep"],"practicalExercise":"Build an offline-capable news application with push alerts and publishable APK.","expectedOutcome":"Publish production-ready mobile applications."}]'::jsonb, ARRAY['Flutter Developer', 'Mobile Application Developer (iOS/Android)', 'Cross-Platform App Engineer', 'Junior Mobile Software Engineer'], '{"name":"[Senior Mobile Engineer at Navya EdTech / Industry Specialist]","role":"Mobile Development Lead","experience":"5+ years publishing commercial Flutter and Android applications","specialization":"Flutter, Dart, Clean Architecture, Mobile State Management","isPlaceholder":true}'::jsonb, '[{"question":"Can I build both Android and iOS apps with this course?","answer":"Yes! Flutter creates unified binaries for both Android and iOS from a single Dart codebase."}]'::jsonb, 'Flutter App Development Course in Nepal | Mobile Training Kathmandu', 'Learn Flutter and Dart mobile app development in Kathmandu with Navya Ed Tech. Build cross-platform Android and iOS apps with practical projects.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('full-stack-career-track', 'Full Stack Engineering Career Program', 'Career Programs', 'An intensive, end-to-end program for candidates preparing for professional software engineering roles.', 'Our flagship multi-tier career program designed to bridge the gap between academic theory and commercial software engineering. Spanning modern frontend, backend systems, database modeling, cloud deployment, code reviews, and structured capstone engineering.', '6 Months (24 Weeks)', 'Classroom Immersion / Intensive Hybrid', 'Graduates or final-year students in CS/IT/Engineering or individuals with dedicated full-time learning commitment.', ARRAY['Fresh graduates looking to secure their first software developer role.', 'Self-taught programmers seeking rigorous industry structure and mentoring.', 'Career switchers wanting a comprehensive, guided technology pathway.'], ARRAY['Comprehensive MERN Stack & TypeScript curriculum', 'Advanced Database Architecture & REST API Design', 'DevOps, Docker & Cloud Deployment fundamentals', '3 major production-grade portfolio projects with senior code reviews', 'Resume reviews, technical interview prep, and project defense sessions'], ARRAY['Ability to build and deploy complex full-stack web applications independently.', 'Strong fluency in Git collaboration workflows, CI/CD, and system architecture.', 'A verifiable GitHub portfolio with live deployed applications.'], ARRAY['MERN Stack Web Development', 'React & Modern Frontend Engineering', 'DevOps & Cloud Engineering Fundamentals']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('applied-data-ai-program', 'Applied Data Science & Machine Learning Program', 'Career Programs', 'Comprehensive data engineering, statistical modeling, and machine learning for modern analytical roles.', 'Designed for analytical professionals and students who want to build real data pipelines, perform rigorous exploratory analysis, train predictive models, and deploy machine learning APIs in production.', '4 Months (16 Weeks)', 'Classroom / Online Live', 'Basic mathematical aptitude (algebra/statistics) and strong motivation for data problem solving.', ARRAY['Economics, statistics, mathematics, and engineering graduates.', 'Business analysts looking to transition to data science and ML engineering.', 'Software developers wanting to add machine learning capabilities.'], ARRAY['Python programming for high-performance computing', 'Pandas, NumPy & SQL Data Warehousing', 'Scikit-Learn Machine Learning Pipelines', 'FastAPI deployment & modern AI model integrations', '2 domain-specific analytics capstone projects'], ARRAY['Ability to extract, clean, and model datasets to drive business decisions.', 'Deployment of machine learning APIs capable of serving live predictions.', 'Statistical reporting and data visualization fluency.'], ARRAY['Python, Data Science & Machine Learning']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('digital-product-design-track', 'UI/UX & Product Design Professional Track', 'Professional Programs', 'A rigorous hands-on program covering UX research, design systems, Figma workflows, and high-impact case study formulation.', 'Equips designers and technologists with the practical methodologies needed to design complex digital experiences. From user interviews and wireframes to scalable Figma design systems and developer handoff.', '3 Months (12 Weeks)', 'Classroom / Hybrid', 'Open to all creative and analytical minds. No prior design software required.', ARRAY['Aspiring UI/UX and product designers.', 'Graphic designers transitioning into digital software product design.', 'Frontend developers wanting to master visual hierarchy and UX design.'], ARRAY['User research, customer journey mapping, and empathy modeling', 'Figma auto-layout, component variants, variables, and design tokens', 'Interactive prototyping and usability testing protocols', '2 detailed UX case studies formatted for international portfolio standards'], ARRAY['Production of an industry-standard digital product portfolio.', 'Mastery of Figma design system creation and management.', 'Confidence in defending design decisions grounded in user research.'], ARRAY['UI/UX & Digital Product Design']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('internship-readiness-pathway', 'Software Engineering Internship Readiness Program', 'Internship Programs', 'Focused preparation for college students and recent graduates targeting software development internships.', 'A targeted program that simulates working in a real software team at Navya EdTech. Focuses on code quality, testing, code reviews, collaborative pull requests, and building software that adheres to commercial standards.', '8 Weeks', 'In-Person Laboratory & Code Sprints', 'Candidates with basic programming knowledge who need practical team engineering experience.', ARRAY['BSc.CSIT, BCA, BIT, Computer Engineering students seeking practical internship preparation.', 'Learners who know syntax but struggle to build complete applications in teams.'], ARRAY['Weekly agile sprint simulations with tickets and standups', 'Git branching strategies, code reviews, and pair programming', 'Testing fundamentals and error handling best practices', 'Capstone team project evaluated by Navya EdTech engineers'], ARRAY['Demonstrated experience collaborating on a multi-developer codebase.', 'Readiness for technical interviews and corporate software internships.', 'Verified performance assessment from industry instructors.'], ARRAY['Practical Team Engineering Workshop']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('RemitFlow: Cross-Border Remittance & Settlement Portal', 'Web', ARRAY['React', 'TypeScript', 'Node.js', 'Express', 'MongoDB', 'Tailwind CSS'], 'A full-stack banking prototype built by students during the MERN Stack Capstone. Features live currency conversion rate calculators, multi-step KYC verification simulation, transaction audit logs, and role-based permissions.', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=800&q=80', 'MERN Stack Web Development Capstone Project', ARRAY['JWT Authentication with refresh token rotation', 'Complex aggregation pipelines for financial transaction reconciliation', 'Responsive design with light/dark accessibility modes'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('CareQueue: OPD Appointment & Real-Time Queue Tracker', 'Web', ARRAY['React', 'Node.js', 'Socket.io', 'Express', 'PostgreSQL'], 'Designed to solve crowding in local Kathmandu hospitals. Patients receive live queue position updates on mobile web while clinic receptionists manage dynamic slot allocations through an administrative dashboard.', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=800&q=80', 'Full Stack Engineering Capstone', ARRAY['WebSocket bi-directional real-time queue streaming', 'SMS notification dispatch integration simulation', 'Role-based doctor, receptionist, and patient portals'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('KrishiForecast: Vegetable Price Trend Predictor (Kalimati Market)', 'Data', ARRAY['Python', 'Pandas', 'Scikit-Learn', 'FastAPI', 'Matplotlib'], 'A machine learning system trained on historical daily price datasets from the Kalimati vegetable market. Predicts price fluctuations for 30+ staples based on seasonal indices and rainfall patterns.', 'https://images.unsplash.com/photo-1595053826286-2e59ef795186?auto=format&fit=crop&w=800&q=80', 'Python & Data Science Capstone Project', ARRAY['Rigorous time-series cleaning and outlier normalization', 'Random Forest regression model with 88% directional accuracy', 'FastAPI REST endpoint serving real-time inferences'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('SajhaYatri: Electric Microbus Ride Booker & Route Tracker', 'Mobile', ARRAY['Flutter', 'Dart', 'Bloc', 'Google Maps SDK', 'Firebase'], 'A mobile application prototype for tracking and pre-booking electric public transit routes in the Kathmandu valley. Features live GPS map simulation and digital ticket QR codes.', 'https://images.unsplash.com/photo-1557404763-69708cd8b9ce?auto=format&fit=crop&w=800&q=80', 'Flutter Mobile App Development Project', ARRAY['Bloc state management with strict unidirectional data flow', 'Smooth 60fps route rendering with vector map overlays', 'Offline-first ticket storage with local SQLite database'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('LekhaPro: Digital Tax Filing UX for Remote Tech Workers', 'UI/UX', ARRAY['Figma', 'User Research', 'Design Systems', 'Prototyping'], 'A comprehensive UX case study addressing the friction Nepali remote software developers face when filing self-employed tax declarations and foreign remittance invoices.', 'https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?auto=format&fit=crop&w=800&q=80', 'UI/UX Digital Product Design Track', ARRAY['12 moderated user interviews with freelance engineers in Nepal', '80+ screen interactive Figma prototype with WCAG AA compliance', 'Comprehensive design token specification for developer handoff'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('NyayaSutra: Legal Document Analysis & Clause Search Engine', 'AI', ARRAY['Python', 'FastAPI', 'Vector Embeddings', 'React'], 'An AI-assisted document parser that ingests legal contracts, extracts key liability clauses, and provides semantic search over hundreds of pages of documentation.', 'https://images.unsplash.com/photo-1450133064473-71024230f91b?auto=format&fit=crop&w=800&q=80', 'Applied AI & Python Project Showcase', ARRAY['High-speed vector chunking and similarity scoring', 'Context-grounded summarization preventing hallucinations', 'Clean search UI with cited source highlighting'], FALSE);
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('navigating-modern-software-engineering-careers-in-nepal', 'Navigating Modern Software Engineering Careers in Nepal: Skills, Portfolios & Industry Demands', 'An objective analysis of how the IT hiring landscape in Kathmandu and remote tech companies has shifted from memorizing syntax to evaluating architecture, Git hygiene, and end-to-end project execution.', 'Nepal IT Industry', 'August 2026', '6 min read', '{"name":"Engineering Advisory Group","role":"Navya EdTech Practitioners"}'::jsonb, 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=800&q=80', ARRAY['The technology employment landscape in Nepal is undergoing a profound evolution. While early industry roles prioritized basic scripting or static website templating, modern product studios and offshore development centers look for candidates who can think in systems, collaborate using Git, and understand deployment mechanics.', 'One of the most frequent gaps our engineering leads observe in fresh university graduates is the separation between theoretical syllabus concepts and practical product engineering. Knowing what an array is does not automatically translate into understanding how to handle asynchronous data fetching without crashing an interface.', 'To build a competitive profile in 2026, engineers need three core pillars: clean architectural fundamentals (such as TypeScript and modular design), practical database fluency with indexing and security in mind, and demonstrated proof of work through verified live projects.'], ARRAY['Career', 'Hiring', 'Software Engineering', 'Nepal Tech']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('why-project-based-learning-outperforms-passive-tutorials', 'The "Tutorial Trap" in Programming: Why Building Under Constraint Drives Real Competency', 'Why watching hours of coding tutorials rarely produces job-ready developers, and how deliberate practice with code reviews builds true problem-solving resilience.', 'Programming', 'July 2026', '5 min read', '{"name":"Technical Education Team","role":"Navya Ed Tech"}'::jsonb, 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?auto=format&fit=crop&w=800&q=80', ARRAY['Passive video consumption creates an illusion of competence. When following a tutorial video step-by-step, the instructor has already solved the architectural dilemmas, handled the edge cases, and cleaned up the bugs off-camera.', 'Real engineering competence begins the moment your build fails and you must inspect stack traces, consult official documentation, and formulate hypotheses to resolve the bug.', 'At Navya Ed Tech, we structure all coursework around guided project sprints with mandatory code critiques. When students learn to defend their schema choices and refactor their own code, their retention and debugging speed increase drastically.'], ARRAY['Learning Methodology', 'Code Reviews', 'Productivity']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('why-typescript-is-essential-for-modern-web-development', 'Why TypeScript Has Become Non-Negotiable in Production Web Teams', 'Exploring how static typing prevents entire classes of runtime defects, improves IDE developer experience, and enables fearless refactoring in growing codebases.', 'Web Development', 'June 2026', '7 min read', '{"name":"Frontend Engineering Guild","role":"Navya EdTech"}'::jsonb, 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80', ARRAY['As web applications grow in complexity, dynamic typing in pure JavaScript often leads to silent runtime errors, difficult refactorings, and undocumented API contracts between teams.', 'TypeScript solves these challenges by providing compile-time type checking, self-documenting data interfaces, and instant auto-completion in modern code editors.', 'In our MERN and React courses, TypeScript is taught alongside core syntax so students build muscle memory with types, interfaces, generics, and strict linting from day one.'], ARRAY['TypeScript', 'React', 'Frontend', 'Best Practices']) ON CONFLICT (slug) DO NOTHING;
